WITH session_summary AS (SELECT session_id, ROUND((100 * SUM(CASE WHEN event_type = 'click' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_click, COUNT(DISTINCT duration_sec) AS unique_event_types FROM web_events GROUP BY session_id) SELECT s.id, s.started_at, s.country, ss.pct_click, ss.unique_event_types FROM sessions s LEFT OUTER JOIN session_summary ss ON s.id = ss.session_id WHERE ss.pct_click > 27 ORDER BY country DESC, s.started_at;
